H('412.d.16.A',4,"Adding a contingency amount to a budget protects against:","unexpected costs",["savings","good luck","early finish"],"Contingency covers surprises.")
H('412.d.16.B',3,"A Bill of Materials cost report multiplies each part's unit cost by its quantity and then:","adds the results",["divides by color","ignores quantities","subtracts the labor"],"The total is the sum of line costs.")
H('412.d.16.B',4,"Three brackets cost 4 dollars each and 10 screws cost 0.50 dollars each. The BOM cost is:","17 dollars",["12.50 dollars","5 dollars","22 dollars"],"12 + 5 = 17.")
H('412.d.16.C',3,"Comparing the final build cost with the estimated budget shows where the team:","over- or under-estimated",["ignored the budget","lost data","won a prize"],"Differences reveal estimation errors.")
H('412.d.16.C',4,"A team estimated 200 dollars but spent 250 dollars. The difference of 50 dollars is called a:","cost overrun",["savings","profit","bonus"],"Spending exceeded the estimate.")
H('412.d.16.D',3,"Monitoring a budget during a project means regularly comparing:","spending to the plan",["colors to the plan","names to the plan","weather to the plan"],"Tracking prevents surprises.")
H('412.d.16.D',4,"If prices rise for a key material, the manager should update the:","budget and inform the team",["design name","date of birth","logo"],"Budgets must reflect reality.")
H('412.d.16.E',3,"A budget status report shows how much has been spent and how much:","remains",["is rumored","is invented","is hidden"],"Spenddown tracks remaining funds.")
H('412.d.16.E',4,"A report that shows spending far ahead of progress should include an explanation of:","the cause of the difference",["the weather","team hobbies","paint choices"],"Reports explain variances.")
H('412.d.16.F',3,"Budget tracking in design projects is important because it helps prevent:","running out of money before finishing",["finishing early","lower quality","more testing"],"Tracking controls spending.")
H('412.d.16.F',4,"Tracking costs over time helps a team make better estimates on:","future projects",["past weather","old lunches","previous holidays"],"History improves estimating.")
H('413.d.1',3,"An aerospace engineer finds a flaw in a flight-critical part after it has been installed. The ethical action is to:","report it immediately so it can be corrected",["wait until the next inspection","keep it secret","hope it holds"],"Safety comes before schedule.")
H('413.d.1',4,"An aerospace engineer is asked to sign off on a test that was not performed. The ethical response is to:","refuse to sign",["sign quickly","sign and hope","delete the request"],"Honest records protect lives.")
H('413.d.2.A',3,"Defining the problem clearly at the start of an aerospace design project helps the team to:","focus on the right needs",["avoid research","skip testing","choose a name"],"A clear problem guides the work.")
H('413.d.2.A',4,"A problem statement for a drone design should include what it must do and its:","constraints",["color","theme song","logo"],"Constraints bound the solution.")
H('413.d.2.B',3,"The research stage of design involves studying existing aircraft and:","relevant principles and data",["unrelated jokes","lunch menus","paint colors"],"Research informs the design.")
H('413.d.2.B',4,"Reading accident reports during research helps designers to avoid repeating:","past failures",["successes","trends in fashion","price lists"],"History teaches safety.")
H('413.d.2.C',3,"Ideation is the process of generating many:","possible solutions",["errors","invoices","rules"],"Ideation widens options.")
H('413.d.2.C',4,"Conceptualization turns ideas into rough concepts that can be:","compared and developed",["forgotten","painted","hidden"],"Concepts are early designs.")
H('413.d.2.D',3,"Selecting a concept for detailed development means comparing ideas against the:","requirements",["weather","lunch plans","parking"],"Requirements drive selection.")
H('413.d.2.D',4,"A team chooses the concept with the best balance of performance, cost, and:","safety",["mood","slogan","color"],"Trade-offs guide choices.")
H('413.d.2.E',3,"A technical drawing differs from a sketch by including:","precise dimensions and standards",["colors only","signatures","jokes"],"Technical drawings follow standards.")
H('413.d.2.E',4,"A scale model of a wing in a wind tunnel is a:","physical model used for testing",["budget","report","contract"],"Models test concepts.")
H('413.d.2.F',3,"Experimental design includes deciding what to measure, how, and under what:","conditions",["colors","nicknames","dates only"],"Controlled conditions give valid data.")
H('413.d.2.F',4,"Running a test several times and averaging the results reduces the effect of:","random error",["gravity","design","requirements"],"Repetition improves reliability.")
H('413.d.2.G',3,"Test results that show too much drag lead the team to:","revise the design and test again",["stop","hide results","change the data"],"Iteration uses results.")
H('413.d.2.G',4,"The design process is iterative because earlier steps are often:","revisited after learning from tests",["forbidden","unnecessary","skipped"],"Learning requires revisiting steps.")
H('413.d.2.H',3,"Communicating an engineering solution effectively requires clear reports, drawings, and:","presentations",["rumors","jokes","guesses"],"Communication shares the design.")
H('413.d.2.H',4,"The purpose of communicating a design is to help others:","understand, evaluate, and build it",["avoid it","forget it","copy it illegally"],"Clear communication enables action.")
H('413.d.3.A',3,"A good way to prioritize tasks is to do first those that are:","urgent and important",["easy and boring","unrelated","optional"],"Priorities protect deadlines.")
H('413.d.3.A',4,"Setting deadlines earlier than the real due date gives the team a:","buffer for problems",["longer vacation","new goal","smaller budget"],"Buffers absorb delays.")
H('413.d.3.B',3,"A constraint on an aircraft design might be a maximum:","weight",["opinion","hobby","slogan"],"Weight limits are typical constraints.")
H('413.d.3.B',4,"Planning around constraints early prevents discovering late that the design is too:","heavy or costly",["colorful","friendly","quiet"],"Early planning avoids rework.")
H('413.d.3.C',3,"A milestone marks:","a major point of progress",["a mistake","lunch","a rumor"],"Milestones track progress.")
H('413.d.3.C',4,"Dividing a long project into smaller deliverables makes it easier to:","track progress and catch problems early",["avoid planning","delay work","hide mistakes"],"Small pieces are manageable.")
H('413.d.3.D',3,"A quick message to a teammate is an example of:","informal communication",["a formal report","a legal contract","a press release"],"Different types suit different needs.")
H('413.d.3.D',4,"A formal design report is better than a text message for communicating:","detailed design decisions for later reference",["a lunch order","a joke","a greeting"],"Formal documents last.")
H('413.d.3.E',3,"A common problem-solving strategy is to break a large problem into:","smaller subproblems",["bigger problems","jokes","rumors"],"Decomposition simplifies problems.")
H('413.d.3.E',4,"Problem solving in teams works best when members:","share ideas and test them",["hide ideas","avoid testing","stop talking"],"Collaboration improves solutions.")
H('413.d.4.A',3,"Giving a critique involves describing, analyzing, interpreting, and:","evaluating the work",["ignoring the work","mocking the author","skipping the details"],"Structured critique is fair.")
H('413.d.4.A',4,"A helpful critique of a wing design says what was observed and how it affects:","performance",["feelings only","appearance of the room","lunch"],"Link observations to impact.")
H('413.d.4.B',3,"Sensemaking in a team means understanding each member's:","strengths and perspectives",["address","age","hairstyle"],"It helps assign work well.")
H('413.d.4.B',4,"Teamwork skills include listening, sharing tasks, and:","meeting commitments",["interrupting","working alone","ignoring deadlines"],"Reliability supports teams.")
H('413.d.4.C',3,"A Gantt chart shows project tasks laid out against:","time",["color","weight","cost only"],"Gantt charts are schedules.")
H('413.d.4.C',4,"A work breakdown structure is a hierarchy that divides a project into:","smaller work items",["bigger problems","random names","drawings only"],"WBS clarifies scope.")
H('413.d.4.D',3,"Contributing to a positive group environment includes:","encouraging others and sharing credit",["blaming others","taking all credit","withholding help"],"Positive culture improves results.")
H('413.d.4.D',4,"A team member who shares resources and helps solve problems is contributing to:","a productive group",["a conflict","a delay","a mistake"],"Helpful behavior builds teams.")
H('413.d.5.A',3,"Professional standards and templates for documents help ensure documents are:","consistent and clear",["unreadable","secret","unfinished"],"Standards improve communication.")
H('413.d.5.A',4,"An executive summary generated from a template should be placed:","at the beginning of the report",["at the very end","in the middle","on a separate planet"],"Readers see key points first.")
H('413.d.5.B',3,"A drawing is the best format to show:","the shape of a wing",["a team vote","a quote","a schedule"],"Drawings show geometry.")
H('413.d.5.B',4,"A table is the best format to communicate:","several measurements for comparison",["a story","a drawing's shape","a joke"],"Tables compare values.")
H('413.d.5.C',3,"Presenting background, then method, then results, then conclusions is a:","logical sequence",["random order","backward order","confusing order"],"A standard order aids reading.")
H('413.d.5.C',4,"Justifying a report's structure means explaining why the order helps the:","reader understand the information",["author rest","printer work","computer run"],"Structure serves the audience.")
H('413.d.6.A',3,"Early attempts at human flight by building flapping-wing machines mostly failed because the machines lacked enough:","power and understanding of lift",["paint","passengers","names"],"Early designers did not yet understand aerodynamics.")
H('413.d.6.A',4,"Otto Lilienthal contributed to flight by flying and recording data from:","gliders",["balloons only","jets","rockets"],"His glider flights informed later designers.")
H('413.d.6.B',3,"The Wright brothers achieved powered, controlled flight in 1903 largely by solving the problem of:","control about three axes",["fuel price","cabin comfort","paint color"],"Control was their key innovation.")
H('413.d.6.B',4,"Wind tunnel experiments by the Wright brothers helped them to improve the design of their:","wings and propellers",["radios","jet engines","landing gear only"],"They tested airfoil shapes.")
H('413.d.6.C',3,"The first practical jet aircraft entered service in the:","1940s",["1800s","1920s","2000s"],"Jet engines were developed around World War II.")
H('413.d.6.C',4,"Jet engines allowed aircraft to fly faster and higher than aircraft with:","piston engines",["no wings","rockets","turbines"],"Jets surpassed piston performance.")
H('413.d.6.D',3,"Early rocket pioneer Robert Goddard launched the first successful:","liquid-fueled rocket",["jet airliner","glider","balloon"],"He flew a liquid-fueled rocket in 1926.")
H('413.d.6.D',4,"Konstantin Tsiolkovsky is known for developing the theory of:","rocket propulsion",["gliding","ballooning","kite flying"],"His rocket equation is foundational.")
H('413.d.6.E',3,"The first human in space was Yuri Gagarin, who flew in:","1961",["1901","1945","1990"],"He orbited Earth in April 1961.")
H('413.d.6.E',4,"The Saturn V rocket is famous for launching the:","Apollo missions to the Moon",["first jet airliner","first satellite","space shuttle"],"Saturn V carried Apollo crews.")
H('413.d.6.F',3,"In the United States, civil aviation is regulated by the:","Federal Aviation Administration",["Food and Drug Administration","Postal Service","National Park Service"],"The FAA sets aviation rules.")
H('413.d.6.F',4,"Regulation of aircraft airworthiness exists mainly to protect:","public safety",["airline profits only","engineers' hobbies","pilot fashion"],"Safety drives regulation.")
H('413.d.7.A',3,"A single-engine land aircraft is abbreviated:","SEL",["MSL","SES","MEL"],"SEL means single-engine land.")
H('413.d.7.A',4,"An aircraft with two engines that operates from water is a:","multi-engine sea aircraft",["single-engine land aircraft","helicopter","glider"],"This is the MES class.")
H('413.d.7.B',3,"An aircraft with a gas turbine driving a propeller is a:","turboprop",["piston aircraft","glider","rocket"],"Turboprops combine turbines and propellers.")
H('413.d.7.B',4,"An aircraft powered by a reciprocating engine is categorized as:","piston-powered",["turbofan","ramjet","rocket"],"Piston engines use cylinders.")
H('413.d.7.C',3,"Comparing aircraft categories shows that small piston aircraft are well suited for:","short-range, low-cost flights",["transoceanic airline service","Mach 2 flights","spaceflight"],"Each category fits certain uses.")
H('413.d.7.C',4,"Large jet airliners are chosen over piston aircraft for long routes because they offer:","higher speed and range",["lower fuel burn per seat on all routes","simpler maintenance","smaller size"],"Jets suit long, fast flights.")
H('413.d.7.D',3,"An emerging aircraft trend that uses multiple electric rotors for urban transport is the:","eVTOL",["biplane","airship only","glider"],"eVTOLs take off vertically on electric power.")
H('413.d.7.D',4,"Airships, which use lighter-than-air gas, are being reconsidered for:","heavy cargo and long endurance",["supersonic travel","dogfights","short sprints"],"Airships offer efficient lift.")
H('413.d.8.A',3,"As altitude increases, air temperature and pressure generally:","decrease in the lower atmosphere",["increase","stay the same","reverse each hour"],"Air thins and cools with height.")
H('413.d.8.A',4,"Air density decreases with altitude, so an aircraft at high altitude generates:","less lift at the same speed and angle",["more lift","the same lift","no weight"],"Lift depends on air density.")
H('413.d.8.B',3,"Rotation of an aircraft about its vertical axis is called:","yaw",["pitch","roll","thrust"],"Yaw turns the nose left or right.")
H('413.d.8.B',4,"Rotation about the lateral axis, which raises or lowers the nose, is:","pitch",["yaw","roll","drag"],"Pitch tilts the nose up or down.")
H('413.d.8.C',3,"The primary control surface used to control roll is the:","aileron",["rudder","elevator","flap"],"Ailerons bank the aircraft.")
H('413.d.8.C',4,"The elevator controls motion about which axis?","pitch axis",["yaw axis","roll axis","vertical stabilizer"],"The elevator changes pitch.")
H('413.d.8.D',3,"The four forces acting on an aircraft in flight are lift, weight, thrust, and:","drag",["friction heat","buoyancy","tension"],"Drag opposes thrust.")
H('413.d.8.D',4,"In straight and level, unaccelerated flight, thrust is equal to:","drag",["lift","weight","pressure"],"Forces are balanced in equilibrium.")
H('413.d.8.E',3,"Weight is the force of gravity acting on an object's:","mass",["color","length","volume"],"W = m x g.")
H('413.d.8.E',4,"An object has a mass of 10 kg. Using g = 9.8 m/s2, its weight is:","98 N",["10 N","9.8 N","980 N"],"10 x 9.8 = 98.")
H('413.d.8.F',3,"A pilot pulled upward in a tight turn feels a g-force greater than 1 g, which makes the pilot feel:","heavier",["lighter","weightless","colder"],"Acceleration increases apparent weight.")
H('413.d.8.F',4,"Weight is a force due to gravity, whereas g-force is a measure of:","acceleration relative to gravity",["mass","volume","density"],"G-force compares acceleration to 1 g.")
H('413.d.8.G',3,"In straight and level flight, the free-body diagram shows lift pointing up and weight pointing:","down",["up","forward","backward"],"Weight acts toward Earth.")
H('413.d.8.G',4,"In a level turn, the lift vector is tilted, so its vertical component must equal the aircraft's:","weight",["thrust","drag","speed"],"Vertical equilibrium holds in a level turn.")
H('413.d.8.H',3,"Increasing engine power changes the amount of:","thrust",["gravity","mass","pressure altitude only"],"Throttle controls thrust.")
H('413.d.8.H',4,"Extending flaps on landing increases both lift and:","drag",["thrust","weight","mass"],"Flaps add camber and drag.")
H('413.d.8.I',3,"The wing, fuselage, and tail are examples of major:","aircraft components",["engines","fuels","instruments only"],"These are structural components.")
H('413.d.8.I',4,"The vertical stabilizer with its rudder helps control:","yaw",["pitch","roll","power"],"The rudder yaws the aircraft.")
H('413.d.8.J',3,"Aerodynamics is the study of how air moves around:","objects",["colors","words","plants"],"It is a subset of aerospace engineering.")
H('413.d.8.J',4,"Aerodynamics applies to aircraft, rockets, and also to:","cars and buildings",["only birds","only boats","only trains"],"Air flows around many objects.")
H('413.d.9.A',3,"A wing generates lift in part because air flowing over the curved top surface has lower:","pressure",["temperature only","mass","color"],"Pressure differences create lift.")
H('413.d.9.A',4,"A wing also generates lift by deflecting air downward, an effect described by Newton's:","third law",["first law of thermodynamics","periodic law","law of gases"],"Action and reaction.")
H('413.d.9.B',3,"Increasing an airfoil's angle of attack, within limits, makes lift:","increase",["decrease","vanish","stay zero"],"More angle produces more lift up to stall.")
H('413.d.9.B',4,"Angle of attack is the angle between the wing's chord line and the:","relative wind",["horizon","fuselage","runway"],"AoA is relative to airflow.")
H('413.d.9.C',3,"On a lift coefficient versus angle of attack chart, the curve rises and then drops sharply after the:","stall angle",["takeoff","landing","cruise"],"The peak is maximum CL.")
H('413.d.9.C',4,"The highest point on a CL versus AoA curve represents:","the maximum lift coefficient",["zero lift","minimum drag","the runway length"],"Maximum CL occurs at the stall angle.")
H('413.d.9.D',3,"A stall occurs when the airflow over the wing:","separates and lift drops sharply",["speeds up","becomes smoother","adds power"],"Flow separation causes the stall.")
H('413.d.9.D',4,"To recover from a stall, a pilot should reduce the:","angle of attack",["thrust forever","wing area","airspeed indicator"],"Lowering the nose restores flow.")
H('413.d.9.E',3,"Drag caused by the shape of an object moving through air is called:","form drag",["gravity","thrust","lift"],"Form drag is shape-related pressure drag.")
H('413.d.9.E',4,"Drag caused by air rubbing along a surface is:","skin friction drag",["induced drag only","wave drag only","weight"],"Surface friction creates drag.")
H('413.d.9.F',3,"When a wing is tilted to a steeper angle of attack, its drag generally:","increases",["decreases to zero","stays zero","flips sign"],"Higher AoA brings more drag.")
H('413.d.9.F',4,"Induced drag is a by-product of producing:","lift",["thrust","weight","heat"],"Lift creates wingtip vortices.")
H('413.d.9.G',3,"A drag coefficient chart plots CD against:","angle of attack",["altitude only","fuel","passenger count"],"CD varies with AoA.")
H('413.d.9.G',4,"On a CD versus AoA chart, the lowest point shows the angle with minimum:","drag coefficient",["lift coefficient","weight","thrust"],"The minimum is the lowest drag.")
H('413.d.9.H',3,"If drag increases during flight and thrust stays the same, the aircraft will:","slow down",["speed up","climb","stay the same"],"Net force becomes negative.")
H('413.d.9.H',4,"Higher drag in cruise reduces range because the engine must burn more:","fuel",["wood","oil paint","water"],"Drag costs fuel.")
H('413.d.9.I',3,"The L/D ratio of a wing is its lift divided by its:","drag",["weight","thrust","speed"],"L/D = lift / drag.")
H('413.d.9.I',4,"A glider with L/D of 30 travels about how far forward for each unit of altitude lost?","30 units",["3 units","300 units","1 unit"],"L/D approximates glide ratio.")
H('413.d.9.J',3,"An L/D chart plots the ratio against:","angle of attack",["time of day","price","passenger weight"],"L/D varies with AoA.")
H('413.d.9.J',4,"The peak of an L/D chart shows the angle with the most:","efficient flight",["drag","stall","turbulence"],"Peak L/D is best efficiency.")
H('413.d.9.K',3,"Flying at the angle of attack for maximum L/D gives the best:","glide distance",["stall","climb rate only","weight"],"Maximum L/D maximizes range in a glide.")
H('413.d.9.K',4,"The angle of attack for best glide is found by locating the:","peak of the L/D curve",["lowest point of the curve","edge of the chart","origin"],"Peak L/D gives optimal glide.")
H('413.d.9.L',3,"A wind turbine blade uses an airfoil shape to produce:","rotational force",["fuel","sound only","fog"],"Lift on the blade turns the rotor.")
H('413.d.9.L',4,"Besides wings, airfoils are used in propellers, fans, and:","helicopter rotors",["bricks","water pipes","bridges only"],"Rotors are rotating wings.")
H('413.d.9.M',3,"An unpowered glider can fly because it converts altitude into:","forward speed",["fuel","heat","thrust from the engine"],"Gliding trades height for speed.")
H('413.d.9.M',4,"A glider can gain altitude by flying in rising air called a:","thermal",["stall","spin","dive"],"Thermals lift gliders.")
H('413.d.10.A',3,"A moment is a force multiplied by the:","perpendicular distance from a point",["time","speed","temperature"],"Moment = force x distance.")
H('413.d.10.A',4,"A 500 N lift force acts 0.4 m behind the center of gravity. The moment about the CG is:","200 N-m",["1,250 N-m","20 N-m","0.0008 N-m"],"500 x 0.4 = 200.")
H('413.d.10.B',3,"The center of gravity of an aircraft is the point where its weight is considered to:","act",["end","vanish","double"],"CG is the balance point.")
H('413.d.10.B',4,"Loading heavy cargo far behind the CG moves the aircraft's CG:","aft",["forward","up only","nowhere"],"CG shifts toward added mass.")
H('413.d.10.C',3,"The center of pressure is the point where total aerodynamic force is considered to:","act on the wing",["be zero","vanish","double"],"CP is the resultant location.")
H('413.d.10.C',4,"As angle of attack changes, the center of pressure on a cambered wing:","moves",["never moves","disappears","stays at the wingtip"],"CP shifts with AoA.")
H('413.d.10.D',3,"For stable flight, the center of gravity should generally be located:","ahead of the center of pressure",["behind the center of pressure","at the wingtip","below the runway"],"This gives a restoring nose-down tendency.")
H('413.d.10.D',4,"If the CG is moved too far aft, the aircraft becomes:","less stable",["more stable","heavier","slower to build"],"Aft CG reduces stability.")
H('413.d.10.E',3,"A model aircraft with an adjustable weight lets students test how changing the CG affects:","stability",["color","sound","price"],"Variable CG shows stability effects.")
H('413.d.10.E',4,"In a model with an adjustable wing position, moving the wing changes the relative locations of the CG and:","center of pressure",["flight plan","paint","control tower"],"Relative position matters.")
H('413.d.11.A',3,"Computer-aided design software is an engineering tool used to create:","digital models of parts",["lunch menus","paper tickets","schedules only"],"CAD builds models.")
H('413.d.11.A',4,"Software that simulates airflow over a wing is called:","computational fluid dynamics software",["word processing software","spreadsheet software only","presentation software"],"CFD predicts flow.")
H('413.d.11.B',3,"In aerospace, simulation tools are used to test designs before:","building expensive hardware",["designing","researching","learning"],"Simulation saves cost.")
H('413.d.11.B',4,"A benefit of finite element analysis for an airframe is that it shows where the structure is:","most highly stressed",["most colorful","most expensive to paint","most popular"],"FEA reveals stress.")
H('413.d.12.A',3,"An atmospheric mission requirement might state the aircraft must carry a given:","payload",["name","flag","logo"],"Payload is a core requirement.")
H('413.d.12.A',4,"A requirement that an aircraft must fly 800 km without refueling is a requirement for:","range",["color","name","color of seats"],"Range is distance per fuel load.")
H('413.d.12.B',3,"A space mission requirement might specify the target:","orbit",["paint","logo","uniform"],"Orbit defines where the spacecraft goes.")
H('413.d.12.B',4,"A mission to deliver a satellite to orbit must meet requirements for payload mass and:","launch vehicle capability",["cabin color","pilot hobbies","parking"],"Rockets must be able to lift the payload.")
H('413.d.12.C',3,"Mission requirements are interrelated because changing one, such as payload mass, can affect:","other requirements like range or cost",["nothing else","only color","only schedule"],"Requirements are linked.")
H('413.d.12.C',4,"Increasing the required range of an aircraft usually increases its:","fuel needs and weight",["wing color","noise only","name"],"More fuel adds weight.")
H('413.d.12.D',3,"A mission requirement for a high cruise altitude affects the aircraft's choice of:","engine and structure",["paint","seat covers","name"],"Altitude drives design.")
H('413.d.12.D',4,"A spacecraft that must survive radiation will need requirements for its:","materials and shielding",["paint color","logo","flight attendants"],"Environment drives design.")
H('413.d.12.E',3,"Mission requirements help determine the aircraft's overall:","size and configuration",["name","logo","slogan"],"They drive the design.")
H('413.d.12.E',4,"An aircraft that must take off from short runways will need a wing designed for high:","lift at low speed",["top speed only","weight","price"],"Short field operation needs lift.")
H('413.d.12.F',3,"A mission profile is a graph or diagram showing how the aircraft's altitude and speed change over:","the flight",["a year","the weather","the factory"],"Profiles trace the mission.")
H('413.d.12.F',4,"A mission profile with a long cruise at altitude puts emphasis on requirements for:","fuel efficiency",["short takeoff","hover","paint"],"Cruise efficiency matters.")
H('413.d.13.A',3,"A piston-powered aircraft produces thrust by using the engine to turn a:","propeller",["jet nozzle","rocket bell","wing"],"The propeller accelerates air backward.")
H('413.d.13.A',4,"Thrust from a propeller is created as the blades push air:","backward",["upward","sideways","forward"],"Reaction pushes the aircraft forward.")
H('413.d.13.B',3,"In a turboprop, the gas turbine drives the propeller through a:","reduction gearbox",["fuel tank","landing gear","wing"],"The gearbox lowers rotational speed.")
H('413.d.13.B',4,"Compared with piston engines, turboprops are generally more efficient at:","medium altitudes and speeds",["very low speeds only","supersonic speed","zero speed"],"Turboprops suit regional flights.")
H('413.d.13.C',3,"A jet engine produces thrust by accelerating a stream of:","hot exhaust gas",["water","paint","wood"],"Exhaust speed produces thrust.")
H('413.d.13.C',4,"The main sections of a basic turbojet are the compressor, combustor, and:","turbine and nozzle",["wing and tail","cabin and seat","wheel and brake"],"Air is compressed, burned, and expelled.")
H('413.d.13.D',3,"Unlike a jet engine, a rocket engine carries its own:","oxidizer",["wings","propeller","landing gear"],"Rockets work in space without air.")
H('413.d.13.D',4,"A rocket can operate in the vacuum of space because it does not need atmospheric:","oxygen",["gravity","light","signals"],"It carries oxidizer.")
H('413.d.13.E',3,"Solid-fuel rockets are used as boosters because they are:","simple and can produce high thrust",["delicate","delicate and reusable only","unable to be stored"],"Solids are simple and powerful.")
H('413.d.13.E',4,"A disadvantage of solid-fuel rockets compared with liquid-fuel rockets is that they are hard to:","throttle or shut down",["store","launch","paint"],"Solids burn until used up.")
H('413.d.13.F',3,"Liquid-fuel rockets can be throttled and restarted, which is useful for:","precise maneuvers in space",["storage","painting","manual labor"],"Liquids allow control.")
H('413.d.13.F',4,"Liquid hydrogen and liquid oxygen are an example of:","liquid propellants",["solid fuel","aircraft fuel","battery chemicals"],"These are common rocket propellants.")
H('413.d.14.A',3,"Common material classes in aerospace design include metals, polymers, ceramics, and:","composites",["liquids","gases","foods"],"Composites combine materials.")
H('413.d.14.A',4,"Carbon fiber reinforced polymer is a:","composite material",["pure metal","ceramic only","liquid"],"It combines fibers and resin.")
H('413.d.14.B',3,"Aluminum alloys have long been used in aircraft skin because they are strong for their:","low weight",["high weight","soft feel","bright color"],"Strength-to-weight ratio is key.")
H('413.d.14.B',4,"Titanium might be chosen for a jet engine part exposed to high heat because it keeps its:","strength at high temperature",["color","price","softness"],"Titanium handles heat.")
H('413.d.14.C',3,"Landing gear parts are often made by forging because forging produces parts with high:","strength",["transparency","softness","porosity"],"Forged metal is strong.")
H('413.d.14.C',4,"A part machined from a solid block of metal is made by:","removing material with cutting tools",["pouring liquid","knitting","painting"],"Machining is subtractive.")
H('413.d.14.D',3,"Choosing an expensive material for a small part may be justified if it:","greatly improves performance or safety",["looks nicer only","costs more","is rare"],"Cost must be balanced with benefit.")
H('413.d.14.D',4,"Manufacturing cost affects design decisions because a design that is hard to make may be too:","expensive to produce",["light","strong","simple"],"Manufacturability matters.")
H('413.d.14.E',3,"If a mission requires a vehicle to survive reentry heat, the material requirements include:","high temperature resistance",["low cost only","bright color","low strength"],"Mission drives materials.")
H('413.d.14.E',4,"A mission requiring very low weight favors materials with a high:","strength-to-weight ratio",["density","cost","hardness only"],"Light structures need efficient materials.")
H('413.d.15.A',3,"A truss structure is built from straight members joined into:","triangles",["circles","spirals","spheres"],"Triangles are rigid.")
H('413.d.15.A',4,"In a monocoque structure, the outer skin carries most of the:","load",["paint","fuel","instruments"],"The skin is the structure.")
H('413.d.15.B',3,"Semi-monocoque structures use a skin supported by internal frames, which gives a good balance of:","strength and weight",["color and size","price and name","noise and heat"],"Most airliners use semi-monocoque.")
H('413.d.15.B',4,"Early fabric-covered small aircraft often used a truss fuselage because it was simple and:","easy to build and repair",["very heavy","very fragile","transparent"],"Trusses suit simple aircraft.")
H('413.d.15.C',3,"A spacecraft that must withstand launch loads and be very light will need a structure chosen to meet its:","mission requirements",["paint plan","logo","uniform"],"Mission drives structure.")
H('413.d.15.C',4,"A high-pressure cabin at altitude calls for a structure that can handle repeated:","pressurization cycles",["paint cycles","lunch breaks","logo changes"],"Fatigue from pressure cycles matters.")
H('413.d.15.D',3,"Stringers in a fuselage are long members running along the:","length of the body",["wings only","tires","antenna"],"Stringers stiffen the skin.")
H('413.d.15.D',4,"Bulkheads and frames in the fuselage help maintain the:","cross-sectional shape",["fuel color","tail length","wing area"],"Frames hold the shape.")
H('413.d.15.E',3,"Ribs in a wing help maintain the airfoil:","shape",["color","price","name"],"Ribs shape the wing.")
H('413.d.15.E',4,"The main load-carrying beam running along a wing is the:","spar",["rib","tire","antenna"],"Spars carry bending loads.")
H('413.d.15.F',3,"Compared with aircraft, spacecraft structures must handle launch loads and a:","vacuum and temperature extremes",["heavy rain","strong crosswind","bird strikes"],"Space is a harsh environment.")
H('413.d.15.F',4,"A spacecraft structure that is only used in orbit can be lighter than a launch vehicle because it does not carry:","aerodynamic loads in flight",["its payload","its instruments","any mass"],"Orbit has no air drag loads.")
H('413.d.16.A',3,"The six Keplerian elements describe the size, shape, and orientation of:","an orbit",["a wing","an engine","a hangar"],"Keplerian elements define orbits.")
H('413.d.16.A',4,"The semi-major axis of an orbit describes the orbit's:","size",["color","speed limit","age"],"It sets the orbit size.")
H('413.d.16.B',3,"Increasing an orbit's eccentricity makes the orbit more:","elongated",["circular","small","slow"],"Eccentricity measures elongation.")
H('413.d.16.B',4,"An orbit with an eccentricity of 0 is:","circular",["parabolic","elongated","impossible"],"Zero means a circle.")
H('413.d.16.C',3,"A communications satellite that must stay over one spot on Earth needs a:","geostationary orbit",["polar orbit","low orbit","suborbital arc"],"Geostationary orbits match Earth's rotation.")
H('413.d.16.C',4,"A satellite that must photograph the entire Earth over time may use a:","polar orbit",["geostationary orbit","suborbital arc","equatorial orbit only"],"Polar orbits cover all latitudes.")
H('413.d.16.D',3,"Operating in space means exposure to extreme temperature changes and:","radiation",["rain","wind","fog"],"Space is a harsh environment.")
H('413.d.16.D',4,"Because there is no air in space, heat leaves a spacecraft mainly by:","radiation",["convection","conduction through air","wind"],"Radiative cooling dominates.")
H('413.d.16.E',3,"A common way to reach orbit is with a multi-stage:","rocket",["glider","bicycle","balloon"],"Rockets provide the needed speed.")
H('413.d.16.E',4,"A capsule returning from orbit slows down using atmospheric drag, a heat shield, and often:","parachutes",["wings only","wheels only","skis"],"Parachutes slow the final descent.")
H('413.d.16.F',3,"A growing trend in space flight is reusable launch vehicles, which can:","lower launch costs",["increase costs","avoid testing","need no fuel"],"Reuse cuts the cost per launch.")
H('413.d.16.F',4,"Small satellites known as CubeSats are growing in use because they are:","low-cost and quick to build",["huge","very expensive","impossible to launch"],"CubeSats are affordable.")
H('413.d.17.A',3,"Aerospace engineers contribute to automotive design by improving:","aerodynamics and materials",["paint names","dealer locations","insurance"],"Cars benefit from aero know-how.")
H('413.d.17.A',4,"Streamlining the shape of a car reduces drag and therefore improves:","fuel economy",["tire price","wind noise only","engine size"],"Less drag saves energy.")
H('413.d.17.B',3,"Commercial uses of aerospace design include airliners, satellites, and:","wind turbines",["picture frames","books","pillows"],"Aerodynamics is used in turbines.")
H('413.d.17.B',4,"Lightweight composites first used in aircraft are now also found in:","bicycles and sporting goods",["only rockets","only bricks","only glass"],"Composites spread to consumer goods.")
H('413.d.17.C',3,"A household item impacted by aerodynamics is a:","ceiling fan",["rug","couch","lamp base"],"Fan blades act like airfoils.")
H('413.d.17.C',4,"A vacuum cleaner, hair dryer, and ceiling fan all depend on moving:","air",["glass","sand","paper"],"Airflow is central to each.")
H('413.d.18.A',3,"Aircraft navigation systems help the pilot determine the aircraft's:","position and route",["lunch","paint","name"],"Navigation finds position.")
H('413.d.18.A',4,"A communication system lets pilots talk to:","air traffic control",["the weather only","the passengers' families","the engine"],"Radios connect pilots and controllers.")
H('413.d.18.B',3,"Satellite-based navigation, such as GPS, is one implementation of aircraft:","navigation systems",["fuel systems","seating systems","paint systems"],"GPS uses satellites.")
H('413.d.18.B',4,"An autopilot is a system that can:","fly the aircraft along a set course",["refuel the aircraft","paint the aircraft","build the aircraft"],"Autopilots hold heading and altitude.")

B.balance()
